func newResumeCmd() *cobra.Command {
	var force bool

	cmd := &cobra.Command{
		Use:   "resume [branch]",
		Short: "Resume a stopped session (interactive picker, or by branch)",
		Long: `Resume an agent session.

With no argument, opens an interactive picker of stopped sessions across all
worktrees so you don't have to remember which branch you left work on. Picking
a session checks out its branch and shows the command to continue the agent. If
the branch is already checked out in another worktree, you'll be pointed there
instead.

With a branch argument, switches to that branch and resumes its session directly:
1. Checks out the specified branch
2. Finds the session ID from commits unique to this branch (not on main)
3. Restores the session log if it doesn't exist locally (an existing local log
   is kept as-is; use --force to overwrite it from the checkpoint)
4. Shows the command to resume the session

If the branch doesn't exist locally but exists on origin, you'll be prompted
to fetch it.

If newer commits without checkpoints exist on the branch (e.g., after merging main
or cherry-picking from elsewhere), this operation will reset your Git status to the
most recent commit with a checkpoint.  You'll be prompted to confirm resuming in this case.`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}

			// Discover external agents so checkpoints from external agents can be resolved.
			external.DiscoverAndRegister(cmd.Context())

			if len(args) == 0 {
				return runResumePicker(cmd.Context(), cmd, force)
			}

			return runResume(cmd.Context(), cmd, args[0], force)
		},
	}

	cmd.Flags().BoolVarP(&force, "force", "f", false, "Resume from older checkpoint without confirmation")

	return cmd
}

func runResume(ctx context.Context, cmd *cobra.Command, branchName string, force bool) error {
	// Only initialize logging when inside a git worktree to avoid
	// creating .entire/logs/ in arbitrary directories.
	if _, err := paths.WorktreeRoot(ctx); err == nil {
		logging.SetLogLevelGetter(GetLogLevel)
		if err := logging.Init(ctx, ""); err == nil {
			defer logging.Close()
		}
	}

	w := cmd.OutOrStdout()
	errW := cmd.ErrOrStderr()

	proceed, err := switchToBranchForResume(ctx, w, errW, branchName, force)
	if err != nil || !proceed {
		return err
	}

	return resumeFromCurrentBranch(ctx, w, errW, branchName, force)
}

// switchToBranchForResume ensures the working tree is on branchName, checking it
// out (or fetching it from origin) as needed. It returns proceed=false with a nil
// error when the user declined to fetch a remote-only branch, so callers should
// stop without treating that as a failure.
func switchToBranchForResume(ctx context.Context, w, errW io.Writer, branchName string, force bool) (bool, error) {
	// Check if we're already on this branch
	currentBranch, err := GetCurrentBranch(ctx)
	if err == nil && currentBranch == branchName {
		return true, nil
	}

	// Check if branch exists locally
	exists, err := BranchExistsLocally(ctx, branchName)
	if err != nil {
		return false, fmt.Errorf("failed to check branch: %w", err)
	}

	if !exists {
		// Branch doesn't exist locally, check if it exists on remote
		remoteExists, err := BranchExistsOnRemote(ctx, branchName)
		if err != nil {
			return false, fmt.Errorf("failed to check remote branch: %w", err)
		}

		if !remoteExists {
			return false, fmt.Errorf("branch '%s' not found locally or on origin", branchName)
		}

		// Ask user if they want to fetch from remote (--force skips the prompt)
		if !force {
			shouldFetch, err := promptFetchFromRemote(branchName)
			if err != nil {
				return false, err
			}
			if !shouldFetch {
				return false, nil
			}
		}

		// Fetch and checkout the remote branch
		fmt.Fprintf(w, "Fetching branch '%s' from origin...\n", branchName)
		if err := FetchAndCheckoutRemoteBranch(ctx, branchName); err != nil {
			fmt.Fprintf(errW, "Error: failed to checkout branch: %v\n", err)
			return false, NewSilentError(errors.New("failed to checkout branch"))
		}
		fmt.Fprintf(w, "✓ Switched to branch %s\n", branchName)
		return true, nil
	}

	// Branch exists locally, check for uncommitted changes before checkout
	hasChanges, err := HasUncommittedChanges(ctx)
	if err != nil {
		return false, fmt.Errorf("failed to check for uncommitted changes: %w", err)
	}
	if hasChanges {
		return false, errors.New("you have uncommitted changes. Please commit or stash them first")
	}

	// Checkout the branch
	if err := CheckoutBranch(ctx, branchName); err != nil {
		fmt.Fprintf(errW, "Error: failed to checkout branch: %v\n", err)
		return false, NewSilentError(errors.New("failed to checkout branch"))
	}
	fmt.Fprintf(w, "✓ Switched to branch %s\n", branchName)
	return true, nil
}

// resumeSessionOnBranch switches to branchName and resumes the specific session
// identified by checkpointID, instead of re-deriving the latest checkpoint on the
// branch. The interactive picker uses this so that selecting one of several
// sessions on the same branch resumes exactly that session.
func resumeSessionOnBranch(ctx context.Context, cmd *cobra.Command, branchName string, checkpointID id.CheckpointID, force bool) error {
	if _, err := paths.WorktreeRoot(ctx); err == nil {
		logging.SetLogLevelGetter(GetLogLevel)
		if err := logging.Init(ctx, ""); err == nil {
			defer logging.Close()
		}
	}

	w := cmd.OutOrStdout()
	errW := cmd.ErrOrStderr()

	proceed, err := switchToBranchForResume(ctx, w, errW, branchName, force)
	if err != nil || !proceed {
		return err
	}

	return resumeByCheckpointID(ctx, w, errW, checkpointID, force)
}

// resumeByCheckpointID restores the session(s) recorded in a specific committed
// checkpoint and prints the resume command(s). Unlike resumeFromCurrentBranch it
// does not search branch history — the caller already knows which checkpoint to
// resume, so two sessions on the same branch resume independently.
func resumeByCheckpointID(ctx context.Context, w, errW io.Writer, checkpointID id.CheckpointID, force bool) error {
	if checkpointID.IsEmpty() {
		return errors.New("no checkpoint to resume")
	}

	// Refresh the checkpoint metadata branch from the remote first so we read the
	// latest checkpoint content even when this checkpoint ID is already resolvable
	// locally (e.g. the session was continued and re-pushed elsewhere, updating
	// the v1 branch content without a new code commit on this branch).
	refreshMetadataFromRemote(ctx, errW)

	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash})
	if err != nil {
		return fmt.Errorf("open checkpoint store: %w", err)
	}
	store := stores.Persistent
	refs := stores.Refs()
	if refs.ReadBootstrappableFromOrigin() {
		promoteRemoteTrackingPrimary(ctx, repo, refs)
	}

	metadata, err := readCheckpointInfoFromStore(ctx, store, checkpointID)
	if err != nil {
		if checkpointpolicy.IsUnsupportedVersion(err) {
			return err
		}
		logging.Debug(ctx, "resume by checkpoint: metadata read failed, checking remote",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", err.Error()),
		)
		return checkRemoteMetadata(ctx, w, errW, checkpointID, stores.Refs())
	}

	return resumeSession(ctx, w, errW, metadata, force)
}

func resumeFromCurrentBranch(ctx context.Context, w, errW io.Writer, branchName string, force bool) error {
	logCtx := logging.WithComponent(ctx, "resume")

	// Refresh the checkpoint metadata branch from the remote before reading, so a
	// checkpoint whose content was updated remotely (without a new code commit on
	// this branch) is picked up even though its ID is already resolvable locally.
	// This runs before opening the repo so the fresh handle sees the fetched refs.
	refreshMetadataFromRemote(ctx, errW)

	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
	result, err := findBranchCheckpoints(repo, branchName)
	if err != nil {
		return err
	}
	if len(result.checkpointIDs) == 0 {
		fmt.Fprintf(w, "No Entire checkpoint found on branch '%s'\n", branchName)
		return nil
	}

	logging.Debug(logCtx, "found checkpoint(s) on branch",
		slog.String("branch", branchName),
		slog.Int("checkpoint_count", len(result.checkpointIDs)),
		slog.String("commit", result.commitHash[:7]),
		slog.Bool("newer_commits_exist", result.newerCommitsExist),
	)

	// If there are newer commits without checkpoints, ask for confirmation.
	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
	if result.newerCommitsExist && !force {
		fmt.Fprintf(w, "Found checkpoint in an older commit.\n")
		fmt.Fprintf(w, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
		fmt.Fprintf(w, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))

		shouldResume, err := promptResumeFromOlderCheckpoint()
		if err != nil {
			return err
		}
		if !shouldResume {
		FilesToDelete:  filesToDelete,
	}, nil
}

// RestoreLogsOnly restores session logs from a logs-only rewind point.
// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
// Does not modify the working directory.
// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
// If force is false, prompts for confirmation when local logs have newer timestamps.
// Returns info about each restored session so callers can print correct per-session resume commands.
func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
	if !point.IsLogsOnly {
		return nil, errors.New("not a logs-only rewind point")
	}

	if point.CheckpointID.IsEmpty() {
		return nil, errors.New("missing checkpoint ID")
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}
	defer repo.Close()

	WarnIfMetadataDisconnected()
	stores, err := cpkg.Open(ctx, repo, cpkg.OpenOptions{BlobFetcher: s.blobFetcher})
	if err != nil {
		return nil, fmt.Errorf("open checkpoint store: %w", err)
	}
	store := stores.Persistent
	summary, err := cpkg.ReadCheckpoint(ctx, store, point.CheckpointID)
	if err != nil {
		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	if err := checkpointpolicy.EnsureCanReadVersion(point.CheckpointID.String(), summary.CheckpointVersion); err != nil {
		return nil, err
	}

	// Get worktree root for agent session directory lookup
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree root: %w", err)
	}

	// Decide per session whether to keep the existing local log or refresh it
	// from the checkpoint. The write loop reads each decision: StatusUnchanged is
	// kept (still reported so the caller prints its resume command),
	// StatusCheckpointNewer is overwritten with an explanatory note, everything
	// else is written silently.
	decision := s.decideRestoreActions(ctx, repoRoot, store, point.CheckpointID, summary, errW, force)

	// Count sessions to restore
	totalSessions := len(summary.Sessions)
	if totalSessions > 1 {
		fmt.Fprintf(w, "Restoring %d sessions from checkpoint:\n", totalSessions)
	}

	// Restore all sessions (oldest to newest, using 0-based indexing)
	var restored []RestoredSession
	for i := range totalSessions {
		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
		if readErr != nil {
			if !errors.Is(readErr, cpkg.ErrNoTranscript) {
				fmt.Fprintf(errW, "  Warning: failed to read session %d: %v\n", i, readErr)
			}
			continue
		}
		if content == nil || len(content.Transcript) == 0 {
			continue
		}

		sessionID := content.Metadata.SessionID
		if sessionID == "" {
			fmt.Fprintf(errW, "  Warning: session %d has no session ID, skipping\n", i)
			continue
		}
		// Checkpoint metadata comes from the shared entire/checkpoints/v1 branch
		// and is attacker-influenceable. Reject path separators/absolute IDs before
		// they reach ResolveSessionFile + Session, which would otherwise let a
		// crafted session ID overwrite files outside the agent session directory.
		if err := validation.ValidateSessionID(sessionID); err != nil {
			fmt.Fprintf(errW, "  Warning: session %d has unsafe session ID %q, skipping: %v\n", i, sessionID, err)
			continue
		}

		// Resolve per-session agent from metadata — skip if agent is unknown
		if content.Metadata.Agent == "" {
			fmt.Fprintf(errW, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
			continue
		}
		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
		if agErr != nil {
			fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
			continue
		}

		// Compute transcript path from current repo location for cross-machine portability.
		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
		if dirErr != nil {
			fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
			continue
		}
		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
		if resolver, ok := sessionAgent.(agent.RestoredSessionPathResolver); ok {
			resolvedFile, resolveErr := resolver.ResolveRestoredSessionFile(sessionAgentDir, sessionID, content.Transcript)
			if resolveErr != nil {
				fmt.Fprintf(errW, "  Warning: failed to resolve restored session path for session %d (%s): %v (using fallback path)\n", i, sessionID, resolveErr)
			} else {
				sessionFile = resolvedFile
			}
		}

		// Get first prompt for display
		promptPreview := ExtractFirstPrompt(content.Prompts)

		// Local log already present and not forcing: keep it untouched, but still
		// report the session so the caller can print its resume command.
		if decision[sessionID] == StatusUnchanged {
			if totalSessions > 1 {
				fmt.Fprintf(w, "  Session %d: keeping existing local log\n", i+1)
			} else {
				fmt.Fprintf(w, "Keeping existing local session log\n")
			}
			restored = append(restored, RestoredSession{
				SessionID: sessionID,
				Agent:     sessionAgent.Type(),
				Prompt:    promptPreview,
				CreatedAt: content.Metadata.CreatedAt,
			})
			continue
		}

		// Tell the user why an existing local log is being overwritten when the
		// checkpoint is the newer side (the common cross-machine case).
		if decision[sessionID] == StatusCheckpointNewer {
			if totalSessions > 1 {
				fmt.Fprintf(w, "  Session %d: checkpoint has newer entries, updating local log\n", i+1)
			} else {
				fmt.Fprintf(w, "Checkpoint has newer entries than the local log; updating it.\n")
			}
		}

		if totalSessions > 1 {
			isLatest := i == totalSessions-1
			if promptPreview != "" {
				if isLatest {
					fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
				} else {
					fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
				}
			}
			fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
		} else {
			fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
		}

		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
			fmt.Fprintf(errW, "    Warning: failed to create directory: %v\n", mkdirErr)
			continue
		}

		agentSession := &agent.AgentSession{
			SessionID:  sessionID,
			AgentName:  sessionAgent.Name(),
			RepoPath:   repoRoot,
			SessionRef: sessionFile,
			NativeData: content.Transcript,
		}
		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
			if totalSessions > 1 {
				fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
				continue
			}
			return nil, fmt.Errorf("failed to write session: %w", writeErr)
		}

		restored = append(restored, RestoredSession{
			SessionID: sessionID,
			Agent:     sessionAgent.Type(),
			Prompt:    promptPreview,
			CreatedAt: content.Metadata.CreatedAt,
		})
	}

	return restored, nil
}

// ResolveAgentForRewind resolves the agent from checkpoint metadata.
func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
	}
	return ag, nil
}

// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
// Returns an empty string if the prompt cannot be read.
func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
	// Get the commit and its tree
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Look for prompt.txt in the metadata directory
	promptPath := metadataDir + "/" + paths.PromptFileName
	promptEntry, err := tree.File(promptPath)
	if err != nil {
		return ""
	}

	content, err := promptEntry.Contents()
	if err != nil {
		return ""
	}

	return ExtractFirstPrompt(content)
}

// SessionRestoreStatus represents the status of a session being restored.
type SessionRestoreStatus int

const (
	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
	StatusUnchanged                                   // Local and checkpoint are the same
	StatusCheckpointNewer                             // Checkpoint cleanly extends the local log (safe to overwrite)
	StatusLocalNewer                                  // Local has a newer last entry than the checkpoint (conflict)
	StatusDiverged                                    // Checkpoint's last entry is newer, but the logs diverged: the local log has entries the checkpoint lacks (conflict)
)

// SessionRestoreInfo contains information about a session being restored.
type SessionRestoreInfo struct {
	SessionID      string
	Prompt         string               // First prompt preview for display
	Status         SessionRestoreStatus // Status of this session
	LocalTime      time.Time
	CheckpointTime time.Time
}

// decideRestoreActions classifies every session in the checkpoint and returns
// the per-session restore decision under the default (non-force) resume policy,
// keyed by session ID, based on which side has the newer last entry:
//   - StatusNew             → restore (no local file yet).
//   - StatusUnchanged       → keep local (identical; restoring is a no-op).
//   - StatusCheckpointNewer → restore: the checkpoint cleanly extends the local
//     log (local is a prefix of it), e.g. another machine continued the session
//     and pushed. It only appends, so nothing local is lost.
//   - StatusLocalNewer      → conflict: the local log has a newer last entry than
//     the checkpoint.
//   - StatusDiverged        → conflict: the checkpoint's last entry is newer but
//     the logs diverged (the local log holds entries the checkpoint lacks), so a
//     plain overwrite would drop local-only work.
//
// Both conflict statuses prompt before overwriting; on decline (or when we can't
// prompt) the decision is demoted to StatusUnchanged so live local work is kept
// rather than silently clobbered.
//
// With force the map is empty, so every session restores unconditionally.
func (s *ManualCommitStrategy) decideRestoreActions(ctx context.Context, repoRoot string, store cpkg.SessionReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary, errW io.Writer, force bool) map[string]SessionRestoreStatus {
	decision := map[string]SessionRestoreStatus{}
	if force {
		return decision
	}

	var conflicts []SessionRestoreInfo
	for _, sess := range s.classifySessionsForRestore(ctx, repoRoot, store, checkpointID, summary) {
		decision[sess.SessionID] = sess.Status
		if sess.Status == StatusLocalNewer || sess.Status == StatusDiverged {
			conflicts = append(conflicts, sess)
		}
	}
	if len(conflicts) > 0 && !ConfirmOverwriteNewerLocalLogs(errW, conflicts) {
		// Declined (or non-interactive): keep the local logs as-is.
		for _, sess := range conflicts {
			decision[sess.SessionID] = StatusUnchanged
		}
	}
	return decision
}

// classifySessionsForRestore checks all sessions in a checkpoint and returns info
// about each session, including whether local logs have newer timestamps.
// repoRoot is used to compute per-session agent directories.
// Sessions without agent metadata are skipped (cannot determine target directory).
func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.SessionReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
	var sessions []SessionRestoreInfo

	totalSessions := len(summary.Sessions)
	// Check all sessions (0-based indexing)
	for i := range totalSessions {
		content, err := store.ReadSessionContent(ctx, checkpointID, i)
		if err != nil || content == nil || len(content.Transcript) == 0 {
			continue
		}

		sessionID := content.Metadata.SessionID
		if sessionID == "" || content.Metadata.Agent == "" {
			continue
		}
		// Skip unsafe session IDs (see RestoreLogsOnly): this path stats the resolved
		// transcript file, so a crafted ID could otherwise probe arbitrary locations.
		if validation.ValidateSessionID(sessionID) != nil {
			continue
		}

		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
		if agErr != nil {
			continue
		}

		// Compute transcript path from current repo location for cross-machine portability.
		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
		if dirErr != nil {
			continue
		}
		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)

		localTime := paths.GetLastTimestampFromFile(localPath)
		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
		status := ClassifyTimestamps(localTime, checkpointTime)
		// ClassifyTimestamps reports StatusNew when the local file has no parseable
		// timestamp — but a present-but-untimestamped log still exists and must not
		// be silently overwritten. Only a truly-absent file counts as new.
		if status == StatusNew {
			if _, statErr := os.Stat(localPath); statErr == nil {
				status = StatusUnchanged
			}
		}
		// A newer checkpoint timestamp alone doesn't prove the checkpoint is a
		// clean forward extension of the local log: two machines could have
		// continued the same session independently. Only treat it as a safe
		// overwrite when the local log is a prefix of the checkpoint; otherwise
		// it's a divergence conflict that must be confirmed, not silently lost.
		if status == StatusCheckpointNewer && !localIsCleanContinuation(localPath, content.Transcript) {
			status = StatusDiverged
		}

		sessions = append(sessions, SessionRestoreInfo{
			SessionID:      sessionID,
			Prompt:         ExtractFirstPrompt(content.Prompts),
			Status:         status,
			LocalTime:      localTime,
			CheckpointTime: checkpointTime,
		})
	}

	return sessions
}

// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
	// Local file doesn't exist (no timestamp found)
	if localTime.IsZero() {
		return StatusNew
	}

	// Can't determine checkpoint time - treat as new/safe
	if checkpointTime.IsZero() {
		return StatusNew
	}

	// Compare timestamps
	if localTime.After(checkpointTime) {
		return StatusLocalNewer
	}
	if checkpointTime.After(localTime) {
		return StatusCheckpointNewer
	}
	return StatusUnchanged
}

// localIsCleanContinuation reports whether the checkpoint transcript is a clean
// forward extension of the on-disk local log. A missing/unreadable local file is
// treated as NOT a clean continuation (conservative: prefer confirming the
// overwrite over silently clobbering whatever is there).
func localIsCleanContinuation(localPath string, checkpoint []byte) bool {
	local, err := os.ReadFile(localPath) //nolint:gosec // path is derived from the agent's session dir
	if err != nil {
		return false
	}
	return TranscriptIsCleanContinuation(local, checkpoint)
}

// TranscriptIsCleanContinuation reports whether checkpoint is a clean forward
// extension of local: every line of local equals the corresponding line of
// checkpoint, and checkpoint has at least as many lines. Transcripts are
// append-only JSONL, so a clean continuation means the checkpoint only appended
// entries and overwriting the local log with it loses nothing. When false the
// two have diverged — the local log holds lines the checkpoint lacks — and
// overwriting would drop local-only work. Blank lines are ignored so a trailing
// newline on either side doesn't register as divergence.
func TranscriptIsCleanContinuation(local, checkpoint []byte) bool {
	localLines := nonBlankLines(local)
	checkpointLines := nonBlankLines(checkpoint)
	if len(localLines) > len(checkpointLines) {
		return false
	}
	for i, line := range localLines {
		if line != checkpointLines[i] {
			return false
		}
	}
	return true
}

func nonBlankLines(data []byte) []string {
	var lines []string
	for _, line := range strings.Split(string(data), "\n") {
		if strings.TrimSpace(line) != "" {
			lines = append(lines, line)
		}
	}
	return lines
}

// StatusToText returns a human-readable status string.
func StatusToText(status SessionRestoreStatus) string {
	switch status {
	case StatusNew:
		return "(new)"
	case StatusUnchanged:
		return "(unchanged)"
	case StatusCheckpointNewer:
		return "(checkpoint is newer)"
	case StatusLocalNewer:
		return "(local is newer)" // shouldn't appear in non-conflict list
	case StatusDiverged:
		return "(diverged)" // shouldn't appear in non-conflict list
	default:
		return ""
	}
}

// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
// session logs that have newer timestamps than the checkpoint versions.
func PromptOverwriteNewerLogs(errW io.Writer, sessions []SessionRestoreInfo) (bool, error) {
	if !interactive.CanPromptInteractively() {
		return false, errors.New("cannot prompt to overwrite local session logs in non-interactive mode; rerun with --force to overwrite or use a TTY to confirm")
	}

	// Separate conflicting and non-conflicting sessions
	var conflicting, nonConflicting []SessionRestoreInfo
	for _, s := range sessions {
		if s.Status == StatusLocalNewer || s.Status == StatusDiverged {
			conflicting = append(conflicting, s)
		} else {
			nonConflicting = append(nonConflicting, s)
		}
	}

	fmt.Fprintf(errW, "\nWarning: overwriting would lose local session log entries the checkpoint doesn't have:\n")
	for _, info := range conflicting {
		// Show prompt if available, otherwise fall back to session ID
		if info.Prompt != "" {
			fmt.Fprintf(errW, "  \"%s\"\n", info.Prompt)
		} else {
			fmt.Fprintf(errW, "  Session: %s\n", info.SessionID)
		}
		fmt.Fprintf(errW, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
		fmt.Fprintf(errW, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
	}

	// Show non-conflicting sessions with their status
	if len(nonConflicting) > 0 {
		fmt.Fprintf(errW, "\nThese other session(s) will also be restored:\n")
		for _, info := range nonConflicting {
			statusText := StatusToText(info.Status)
			if info.Prompt != "" {
				fmt.Fprintf(errW, "  \"%s\" %s\n", info.Prompt, statusText)
			} else {
				fmt.Fprintf(errW, "  Session: %s %s\n", info.SessionID, statusText)
			}
		}
	}

	fmt.Fprintf(errW, "\nOverwriting will lose the newer local entries.\n\n")

	var confirmed bool
	form := huh.NewForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Overwrite local session logs with checkpoint versions?").
				Value(&confirmed),
		),
	)
	if isAccessibleMode() {
		form = form.WithAccessible(true)
	}

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

// ConfirmOverwriteNewerLocalLogs reports whether local logs that are newer than
// the checkpoint should be overwritten. It prompts interactively; when we can't
// prompt (non-TTY/CI), it never silently clobbers newer local work — it keeps
// the local logs and tells the user to rerun with --force. Errors from the
// prompt are treated as "keep" so a resume is never aborted by a single
// conflicting session.
func ConfirmOverwriteNewerLocalLogs(errW io.Writer, conflicts []SessionRestoreInfo) bool {
	if !interactive.CanPromptInteractively() {
		for _, info := range conflicts {
			label := info.Prompt
			if label == "" {
				label = info.SessionID
			}
			fmt.Fprintf(errW, "Keeping local session log %q: it has entries the checkpoint doesn't (use --force to overwrite).\n", label)
		}
		return false
	}
	overwrite, err := PromptOverwriteNewerLogs(errW, conflicts)
	if err != nil {

Chunk ID: df2b87
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 8388
Output:
	}

	logging.Debug(logCtx, "found checkpoint(s) on branch",
		slog.String("branch", branchName),
		slog.Int("checkpoint_count", len(result.checkpointIDs)),
		slog.String("commit", result.commitHash[:7]),
		slog.Bool("newer_commits_exist", result.newerCommitsExist),
	)

	// If there are newer commits without checkpoints, ask for confirmation.
	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
	if result.newerCommitsExist && !force {
		fmt.Fprintf(w, "Found checkpoint in an older commit.\n")
		fmt.Fprintf(w, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
		fmt.Fprintf(w, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))

		shouldResume, err := promptResumeFromOlderCheckpoint()
		if err != nil {
			return err
		}
		if !shouldResume {
			fmt.Fprintf(w, "Resume cancelled.\n")
			return nil
		}
	}

	checkpointID := result.checkpointIDs[0]
	var metadata *strategy.CheckpointInfo

	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash})
	if err != nil {
		return fmt.Errorf("open checkpoint store: %w", err)
	}
	store := stores.Persistent

	refs := stores.Refs()
	if refs.ReadBootstrappableFromOrigin() {
		promoteRemoteTrackingPrimary(ctx, repo, refs)
	}

	// Multiple checkpoints (squash merge): resolve latest by CreatedAt timestamp.
	if len(result.checkpointIDs) > 1 {
		latestMetadata, found, err := resolveLatestCheckpoint(ctx, store, result.checkpointIDs)
		if err != nil {
			return err
		}
		if !found {
			// No metadata available — nothing to resume from
			logging.Warn(logCtx, "no checkpoint metadata resolved",
				slog.Int("checkpoint_count", len(result.checkpointIDs)),
			)
			fmt.Fprintf(w, "Found %d checkpoints for commit %s but metadata is not available\n",
				len(result.checkpointIDs), result.commitHash[:7])
			return checkRemoteMetadata(ctx, w, errW, result.checkpointIDs[0], stores.Refs())
		}
		olderSkipped := len(result.checkpointIDs) - 1
		fmt.Fprintf(w, "Found %d checkpoints for commit %s, resuming from the latest checkpoint (%d older checkpoint(s) skipped)\n",
			len(result.checkpointIDs), result.commitHash[:7], olderSkipped)
		checkpointID = latestMetadata.CheckpointID
		metadata = latestMetadata
	}

	if metadata == nil {
		storeInfo, storeErr := readCheckpointInfoFromStore(ctx, store, checkpointID)
		if storeErr == nil {
			metadata = storeInfo
		} else {
			if checkpointpolicy.IsUnsupportedVersion(storeErr) {
				return storeErr
			}
			logging.Debug(ctx, "checkpoint store metadata read failed",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("error", storeErr.Error()),
			)
			logging.Warn(logCtx, "checkpoint metadata read failed, checking remote",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("error", storeErr.Error()),
			)
			return checkRemoteMetadata(ctx, w, errW, checkpointID, stores.Refs())
		}
	}

	logging.Debug(logCtx, "checkpoint metadata read successfully",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", metadata.SessionID),
		slog.Int("session_count", metadata.SessionCount),
	)

	return resumeSession(ctx, w, errW, metadata, force)
}

// resolveLatestCheckpoint reads metadata for each checkpoint ID and returns the
// checkpoint with the latest CreatedAt.
func resolveLatestCheckpoint(ctx context.Context, store checkpointInfoReader, checkpointIDs []id.CheckpointID) (*strategy.CheckpointInfo, bool, error) {
	infoMap := make(map[id.CheckpointID]strategy.CheckpointInfo, len(checkpointIDs))
	for _, cpID := range checkpointIDs {
		metadata, readErr := readCheckpointInfoFromStore(ctx, store, cpID)
		if readErr != nil {
			logging.Debug(ctx, "resolveLatestCheckpoint: checkpoint metadata read failed",
				slog.String("checkpoint_id", cpID.String()),
				slog.String("error", readErr.Error()),
			)
			return nil, false, readErr
		}
		infoMap[cpID] = *metadata
	}
	latest, found := strategy.ResolveLatestCheckpointFromMap(checkpointIDs, infoMap)
	if !found {
		return nil, false, nil
	}
	return &latest, true, nil
}

type checkpointInfoReader interface {
	checkpoint.CheckpointReader
	ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.Metadata, error)
}

func readCheckpointInfoFromStore(ctx context.Context, store checkpointInfoReader, checkpointID id.CheckpointID) (*strategy.CheckpointInfo, error) {
	summary, err := checkpoint.ReadCheckpoint(ctx, store, checkpointID)
	if err != nil {
		return nil, fmt.Errorf("read checkpoint: %w", err)
	}
	if err := checkpointpolicy.EnsureCanReadVersion(checkpointID.String(), summary.CheckpointVersion); err != nil {
		return nil, err
	}
	info := &strategy.CheckpointInfo{
		CheckpointID:     checkpointID,
		CheckpointsCount: summary.CheckpointsCount,
		FilesTouched:     summary.FilesTouched,
		SessionCount:     len(summary.Sessions),
	}
	for i := range summary.Sessions {
		metadata, metaErr := store.ReadSessionMetadata(ctx, checkpointID, i)
		if metaErr != nil {
			logging.Debug(ctx, "read checkpoint metadata: session metadata read failed",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.Int("session_index", i),
				slog.String("error", metaErr.Error()),
			)
			continue
		}
		info.SessionIDs = append(info.SessionIDs, metadata.SessionID)
		if metadata.SessionID != "" {
			info.SessionID = metadata.SessionID
			info.CreatedAt = metadata.CreatedAt
			info.Agent = metadata.Agent
			info.IsTask = metadata.IsTask
			info.ToolUseID = metadata.ToolUseID
		}
	}
	if info.SessionID == "" {
		return nil, checkpoint.ErrCheckpointNotFound
	}
	return info, nil
}

func readCheckpointInfoFromRef(
	ctx context.Context,
	repo *git.Repository,
	refs checkpoint.PersistentRefs,
	checkpointID id.CheckpointID,
) (*strategy.CheckpointInfo, error) {
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{Refs: &refs, BlobFetcher: FetchBlobsByHash})
	if err != nil {
		return nil, fmt.Errorf("open checkpoint store: %w", err)
	}
	return readCheckpointInfoFromStore(ctx, stores.Persistent, checkpointID)
}

// getMetadataTree returns the metadata branch tree and a fresh repo handle.
// After a fetch, go-git's storer cache may be stale (new packfiles on disk
// are invisible to the repo opened before the fetch). To avoid this, each
// attempt opens a fresh repo after the fetch succeeds.
//
// Fallback order: treeless fetch → local → checkpoint_remote → full origin fetch → remote tree.
func getMetadataTree(ctx context.Context) (*object.Tree, *git.Repository, error) {
	logCtx := logging.WithComponent(ctx, "resume.getMetadataTree")

	refs := checkpoint.ResolveRefs(ctx)

	// Helper to log ref hash for a repo's primary metadata ref
	logRefHash := func(repo *git.Repository, source string) {
		ref, refErr := repo.Reference(refs.Primary, true)
		if refErr != nil {
			logging.Debug(logCtx, "primary metadata ref not found",
				slog.String("source", source),
				slog.String("error", refErr.Error()),
			)
			return
		}
		logging.Debug(logCtx, "primary metadata ref resolved",
			slog.String("source", source),
			slog.String("ref_hash", ref.Hash().String()),
		)
	}

	// When checkpoint_remote is configured, try it first — that's where
	// checkpoint data lives. Avoids a wasted fetch from origin (which may
	// not have the metadata branch at all).
	if fetchErr := FetchMetadataFromCheckpointRemote(ctx); fetchErr == nil {
		freshRepo, freshErr := openRepository(ctx)
		if freshErr == nil {
			logRefHash(freshRepo, "checkpoint-remote")
			metadataTree, treeErr := strategy.GetMetadataRefTree(freshRepo, refs.Primary)
			if treeErr == nil {
				logging.Debug(logCtx, "metadata tree obtained via checkpoint remote fetch",
					slog.String("tree_hash", metadataTree.Hash.String()),
				)
				return metadataTree, freshRepo, nil
			}
			logging.Debug(logCtx, "checkpoint remote fetch succeeded but tree read failed",
				slog.String("error", treeErr.Error()),
			)
			_ = freshRepo.Close()
		}
	} else {
		logging.Debug(logCtx, "checkpoint remote fetch skipped or failed",
			slog.String("error", fetchErr.Error()),
		)
	}

	// Tip-only fetch (--depth=1) is cheap and always runs so the local lookup
	// below doesn't return stale data.
	if fetchErr := FetchMetadataTreeOnly(ctx); fetchErr == nil {
		freshRepo, repoErr := openRepository(ctx)
		if repoErr == nil {
			logRefHash(freshRepo, "treeless-fetch")
			metadataTree, treeErr := strategy.GetMetadataRefTree(freshRepo, refs.Primary)
			if treeErr == nil {
				logging.Debug(logCtx, "metadata tree obtained via treeless fetch",
					slog.String("tree_hash", metadataTree.Hash.String()),
				)
				return metadataTree, freshRepo, nil
			}
			logging.Debug(logCtx, "treeless fetch succeeded but tree read failed",
				slog.String("error", treeErr.Error()),
			)
			_ = freshRepo.Close()
		}
	} else {
		logging.Debug(logCtx, "treeless fetch failed, trying local",
			slog.String("error", fetchErr.Error()),
		)
	}

	// Try local (may have been set by a prior fetch or push)
	localRepo, repoErr := openRepository(ctx)
	if repoErr == nil {
		logRefHash(localRepo, "local")
		metadataTree, err := strategy.GetMetadataRefTree(localRepo, refs.Primary)
		if err == nil {
			logging.Debug(logCtx, "metadata tree obtained from local branch",
				slog.String("tree_hash", metadataTree.Hash.String()),
			)
			return metadataTree, localRepo, nil
		}
		logging.Debug(logCtx, "local metadata branch not available",
			slog.String("error", err.Error()),
		)
		_ = localRepo.Close()
	}

	// Fallback: full fetch from origin
	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
		freshRepo, repoErr := openRepository(ctx)
		if repoErr == nil {
			logRefHash(freshRepo, "full-fetch")
			metadataTree, treeErr := strategy.GetMetadataRefTree(freshRepo, refs.Primary)
			if treeErr == nil {
				logging.Debug(logCtx, "metadata tree obtained via full fetch",
					slog.String("tree_hash", metadataTree.Hash.String()),
				)
				return metadataTree, freshRepo, nil
			}
			logging.Debug(logCtx, "full fetch succeeded but tree read failed",
				slog.String("error", treeErr.Error()),
			)
			_ = freshRepo.Close()
		}
	} else {
		logging.Debug(logCtx, "full fetch failed",
			slog.String("error", fetchErr.Error()),
		)
	}

	// Try remote tree directly (origin's tracking ref for Primary)
	remoteRepo, repoErr := openRepository(ctx)
	if repoErr != nil {
		return nil, nil, fmt.Errorf("failed to open repository: %w", repoErr)
	}
	logRefHash(remoteRepo, "remote-tracking")
	remoteTree, remoteErr := strategy.GetRemotePrimaryTree(ctx, remoteRepo)
	if remoteErr == nil {
		logging.Debug(logCtx, "metadata tree obtained from remote-tracking branch")
		return remoteTree, remoteRepo, nil
	}
	logging.Debug(logCtx, "remote metadata tree also not available",
		slog.String("error", remoteErr.Error()),
	)
	_ = remoteRepo.Close()

	return nil, nil, fmt.Errorf("metadata branch not available: %w", remoteErr)
}

// branchCheckpointsResult contains the result of searching for checkpoints on a branch.
type branchCheckpointsResult struct {
	checkpointIDs     []id.CheckpointID
	commitHash        string
	commitMessage     string
	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
	newerCommitCount  int  // count of branch-only commits without checkpoints
}

// findBranchCheckpoints finds the most recent commit with an Entire-Checkpoint trailer
// among commits that are unique to this branch (not reachable from the default branch).
// This handles the case where main has been merged into the feature branch.
func findBranchCheckpoints(repo *git.Repository, branchName string) (*branchCheckpointsResult, error) {
	result := &branchCheckpointsResult{}

	// Get HEAD commit
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	// First, check if HEAD itself has a checkpoint (most common case)
	if cpIDs := trailers.ParseAllCheckpoints(headCommit.Message); len(cpIDs) > 0 {
		result.checkpointIDs = cpIDs
		result.commitHash = head.Hash().String()
		result.commitMessage = headCommit.Message
		result.newerCommitsExist = false
		return result, nil
	}

	// HEAD doesn't have a checkpoint - find branch-only commits
	// Get the default branch name
	defaultBranch := getDefaultBranchFromRemote(repo)
	if defaultBranch == "" {
		// Fallback: try common names
		for _, name := range []string{defaultBaseBranch, masterBaseBranch} {
			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
				defaultBranch = name
				break
			}
		}
	}

	// If we can't find a default branch, or we're on it, just walk all commits
	if defaultBranch == "" || defaultBranch == branchName {
		return findCheckpointInHistory(headCommit, nil), nil
	}

	// Get the default branch reference
	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
	if err != nil {
		// Default branch doesn't exist locally, fall back to walking all commits
		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
	}

	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
	if err != nil {
		// Can't get default commit, fall back to walking all commits
		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
	}

	// Find merge base
	mergeBase, err := headCommit.MergeBase(defaultCommit)
	if err != nil || len(mergeBase) == 0 {
		// No common ancestor, fall back to walking all commits
		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
	}

	// Walk from HEAD to merge base, looking for checkpoint
	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
}

// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
// If stopAt is provided, stops when reaching that commit (exclusive).
// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
// It distinguishes between merge commits (bringing in other branches) and regular commits
// (actual branch work) to avoid false warnings after merging main.
func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointsResult {
	result := &branchCheckpointsResult{}
	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
	const maxCommits = 100 // Limit search depth
	totalChecked := 0

	current := start
	for current != nil && totalChecked < maxCommits {
		// Stop if we've reached the boundary
		if stopAt != nil && current.Hash == *stopAt {
			break
		}

		// Check for checkpoint trailer
		if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
			result.checkpointIDs = cpIDs
			result.commitHash = current.Hash.String()
			result.commitMessage = current.Message
			// Only warn about branch work commits, not merge commits
			result.newerCommitsExist = branchWorkCommits > 0
			result.newerCommitCount = branchWorkCommits
			return result
		}

		// Only count regular commits (not merge commits) as "branch work"
		if current.NumParents() <= 1 {
			branchWorkCommits++
		}

		totalChecked++

		// Move to parent (first parent for merge commits - follows the main line)
		if current.NumParents() == 0 {
			break
		}
		parent, err := current.Parent(0)
		if err != nil {
			// Can't get parent, treat as end of history
			break
		}
		current = parent
	}

	// No checkpoint found
	return result
}

// promptResumeFromOlderCheckpoint asks the user if they want to resume from an older checkpoint.
func promptResumeFromOlderCheckpoint() (bool, error) {
	var confirmed bool

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Resume from this older checkpoint?").
				Value(&confirmed),
		),
	)

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

// checkRemoteMetadata checks if checkpoint metadata exists on the remote and
// fetches it if available. Skips when reads don't target a ref origin tracks.
func checkRemoteMetadata(
	ctx context.Context,
	w, errW io.Writer,
	checkpointID id.CheckpointID,
	refs checkpoint.PersistentRefs,
) error {
	logCtx := logging.WithComponent(ctx, "resume.checkRemoteMetadata")

	if !refs.ReadBootstrappableFromOrigin() {
		fmt.Fprintf(errW, "Checkpoint '%s' found in commit but metadata is not available in %s.\n", checkpointID, refs.Read)
		fmt.Fprintf(errW, "This ref is local-only. Try: entire explain %s\n", checkpointID)
		return nil
	}

	// Open a fresh repo to avoid stale packfile index issues
	repo, repoErr := openRepository(ctx)
	if repoErr != nil {
		logging.Warn(logCtx, "failed to open repository for remote check",
			slog.String("error", repoErr.Error()),
		)
		fmt.Fprintf(errW, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
		return nil
	}
	defer repo.Close()

	// Resolve checkpoint remote URL once; reuse for both fetch and error message.
	hasCheckpointRemote := remote.Configured(ctx)
	var unsupportedVersionErr error

	// Try checkpoint_remote first if configured and resolved (that's where checkpoints are stored)
	var checkpointURL string
	var resolveErr error
	if hasCheckpointRemote {
		checkpointURL, resolveErr = remote.FetchURL(ctx)
		if resolveErr == nil {
			if fetchErr := strategy.FetchMetadataBranch(ctx, checkpointURL); fetchErr == nil {
				freshRepo, freshErr := openRepository(ctx)
				if freshErr != nil {
					logging.Debug(logCtx, "checkpoint remote: open repository failed after fetch",
						slog.String("error", freshErr.Error()),
					)
				} else {
					defer freshRepo.Close()
					metadata, err := readCheckpointInfoFromRef(ctx, freshRepo, refs, checkpointID)
					if err != nil {
						if checkpointpolicy.IsUnsupportedVersion(err) {
							unsupportedVersionErr = err
						}
						logging.Debug(logCtx, "checkpoint remote: fetch succeeded but checkpoint metadata read failed",
							slog.String("checkpoint_id", checkpointID.String()),
							slog.String("error", err.Error()),
						)
					} else {
						return resumeSession(ctx, w, errW, metadata, false)
					}
				}
			} else {
				logging.Debug(logCtx, "checkpoint remote fetch failed",
					slog.String("error", fetchErr.Error()),
				)
			}
		}
	}

	// Fall back to origin's remote-tracking branch
	promoteRemoteTrackingPrimary(ctx, repo, refs)
	metadata, metadataErr := readCheckpointInfoFromRef(ctx, repo, refs, checkpointID)
	if metadataErr == nil {
		return resumeSession(ctx, w, errW, metadata, false)
	}
	if checkpointpolicy.IsUnsupportedVersion(metadataErr) {
		unsupportedVersionErr = metadataErr
	}
	logging.Debug(logCtx, "remote-tracking metadata read failed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("error", metadataErr.Error()),
	)

	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
		freshRepo, freshErr := openRepository(ctx)
		if freshErr != nil {
			logging.Debug(logCtx, "origin metadata fetch succeeded but repository reopen failed",
				slog.String("error", freshErr.Error()),
			)
		} else {
			defer freshRepo.Close()
			metadata, err := readCheckpointInfoFromRef(ctx, freshRepo, refs, checkpointID)
			if err != nil {
				if checkpointpolicy.IsUnsupportedVersion(err) && unsupportedVersionErr == nil {
					unsupportedVersionErr = err
				}
				logging.Debug(logCtx, "origin metadata fetch succeeded but checkpoint metadata read failed",
					slog.String("checkpoint_id", checkpointID.String()),
					slog.String("error", err.Error()),
				)
			} else {
				return resumeSession(ctx, w, errW, metadata, false)
			}
		}
	} else {
		logging.Debug(logCtx, "origin metadata fetch failed",
			slog.String("error", fetchErr.Error()),
		)
	}
	if unsupportedVersionErr != nil {
		return unsupportedVersionErr
	}

	// Nothing worked — print helpful error message
	if hasCheckpointRemote {
		if resolveErr != nil {
			fmt.Fprintf(errW, "Checkpoint '%s' found in commit but the checkpoint remote URL could not be resolved: %s\n", checkpointID, resolveErr)
		} else {
			fmt.Fprintf(errW, "Checkpoint '%s' found in commit but its metadata could not be fetched from the checkpoint remote.\n", checkpointID)
		}
		fmt.Fprintf(errW, "Ensure you have access to the checkpoint remote configured in .entire/settings.json.\n")
	} else {
		fmt.Fprintf(errW, "Checkpoint '%s' found in commit but the entire/checkpoints/v1 branch is not available locally or on the remote.\n", checkpointID)
		fmt.Fprintf(errW, "This can happen if the metadata branch was not pushed. Try:\n")
		fmt.Fprintf(errW, "  git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
	}
	return nil
}

// refreshMetadataFromRemote best-effort fetches the latest checkpoint metadata
// branch from the checkpoint remote (or origin) and advances the local primary
// ref to match. Resume otherwise reads checkpoint content straight from the local
// store and never notices that the remote has a newer version of the *same*
// checkpoint ID — the case where a session was continued and re-pushed from
// another machine, updating the v1 branch content without a new code commit on
// the working branch. The fetch helpers advance the local primary ref (via
// SafelyAdvanceLocalRef, which never drops local-only commits), so a subsequently
// opened repo reads the fresh content. Failures (offline, no remote, branch not
// on origin yet) are logged and ignored so resume still works from local data.
func refreshMetadataFromRemote(ctx context.Context, errW io.Writer) {
	refs := checkpoint.ResolveRefs(ctx)
	if !refs.ReadBootstrappableFromOrigin() {
		return
	}

	// Surface a spinner while the network fetch runs so resume doesn't appear to
	// hang. startSpinner only animates once the fetch exceeds its initial delay
	// (no flicker on warm runs) and prints nothing on non-terminal writers;
	// stop(false) erases the transient line — the real resume output follows.
	stop := startSpinner(errW, "Checking remote for newer checkpoints")
	defer stop(false)

	// Prefer the checkpoint remote when configured — that's where checkpoints
	// live, and they may not exist on origin at all.
	if remote.Configured(ctx) {
		err := FetchMetadataFromCheckpointRemote(ctx)
		if err == nil {
			return
		}
		logging.Debug(ctx, "resume: checkpoint-remote metadata refresh failed, trying origin",
			slog.String("error", err.Error()),
		)
	}

	// Tree-only fetch from origin is cheap (blobs are pulled on demand by the
	// checkpoint store's BlobFetcher) and incremental after the first fetch.
	if err := FetchMetadataTreeOnly(ctx); err != nil {
		logging.Debug(ctx, "resume: metadata refresh from origin failed, using local checkpoint data",
			slog.String("error", err.Error()),
		)
	}
}

// promoteRemoteTrackingPrimary advances the local primary ref to match origin's
// remote-tracking ref. Without this, callers reading checkpoint metadata via
// the local ref miss checkpoints already fetched into refs/remotes/origin/...:
// the committed-checkpoint store only falls back to origin/... when the local
// ref is *missing*, not when it's behind. No-op when Primary isn't in Push
// (no remote-tracking ref exists).
func promoteRemoteTrackingPrimary(ctx context.Context, repo *git.Repository, refs checkpoint.PersistentRefs) {
	if !refs.PrimaryFetchableFromOrigin() {
		return
	}
	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", refs.Primary.Short()), true)
	if err != nil {
		return
	}

	if err := strategy.SafelyAdvanceLocalRef(ctx, repo, refs.Primary, remoteRef.Hash()); err != nil {
		logging.Debug(ctx, "failed to promote remote-tracking primary ref",
			slog.String("error", err.Error()),
		)
	}
}

// resumeSession restores and displays the resume command for a specific session.
// For multi-session checkpoints, restores ALL sessions and shows commands for each.
// If force is false, prompts for confirmation when local logs have newer timestamps.
// The caller must provide the already-resolved checkpoint metadata to avoid redundant lookups
// and to support both local and remote metadata trees.
func resumeSession(ctx context.Context, w, errW io.Writer, metadata *strategy.CheckpointInfo, force bool) error {
	checkpointID := metadata.CheckpointID
	sessionID := metadata.SessionID

	// Resolve agent from checkpoint metadata (same as rewind)
	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
	if err != nil {
		return fmt.Errorf("failed to resolve agent: %w", err)
	}

	// Initialize logging context with agent
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())

	logging.Debug(logCtx, "resume session started",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", sessionID),
	)

	// Get worktree root for session directory lookup
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("failed to get worktree root: %w", err)
	}

	sessionDir, err := ag.GetSessionDir(repoRoot)
	if err != nil {
		return fmt.Errorf("failed to determine session directory: %w", err)
	}

	// Create directory if it doesn't exist
	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// Get strategy and restore sessions using full checkpoint data
	strat := GetStrategy(ctx)

	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
	// Create a logs-only rewind point with Agent populated (same as rewind)
	point := strategy.RewindPoint{
		IsLogsOnly:   true,
		CheckpointID: checkpointID,
		Agent:        metadata.Agent,
	}

	sessions, restoreErr := strat.RestoreLogsOnly(ctx, w, errW, point, force)
	if restoreErr != nil || len(sessions) == 0 {
		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
		return resumeSingleSession(ctx, w, errW, ag, sessionID, checkpointID, repoRoot, force)
	}

	logging.Debug(logCtx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int("session_count", len(sessions)),
	)

	return displayRestoredSessions(w, sessions)
}

// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
	sort.SliceStable(sessions, func(i, j int) bool {
		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
	})

	if len(sessions) > 1 {
		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue:\n", len(sessions))
	} else if len(sessions) == 1 {
		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
		fmt.Fprintf(w, "\nTo continue this session:\n")
	}

	isMulti := len(sessions) > 1
	for i, sess := range sessions {
		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
		if err != nil {
			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
		}
		printSessionCommand(w, sessionAgent.FormatResumeCommand(sess.SessionID), sess.Prompt, isMulti, i == len(sessions)-1)
	}

	return nil
}

// resumeSingleSession restores a single session (fallback when multi-session restore fails).
// By default it never overwrites an existing local session log — if one is present it is
// kept and only the resume command is printed; --force overwrites it from the checkpoint.
// A missing local log is always restored from the checkpoint.
func resumeSingleSession(ctx context.Context, w, errW io.Writer, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
	if err != nil {
		return fmt.Errorf("failed to resolve transcript path: %w", err)
	}

	printResumeCmd := func() {
		fmt.Fprintf(w, "\nTo continue this session:\n")
		fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
	}

	if checkpointID.IsEmpty() {
		logging.Debug(ctx, "resume session: empty checkpoint ID",
			slog.String("checkpoint_id", checkpointID.String()),
		)
		fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
		printResumeCmd()
		return nil
	}

	repo, repoErr := openRepository(ctx)
	if repoErr != nil {
		return fmt.Errorf("failed to open repository: %w", repoErr)
	}
	defer repo.Close()
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash})
	if err != nil {
		return fmt.Errorf("open checkpoint store: %w", err)
	}
	summary, err := checkpoint.ReadCheckpoint(ctx, stores.Persistent, checkpointID)
	if err == nil {
		err = checkpointpolicy.EnsureCanReadVersion(checkpointID.String(), summary.CheckpointVersion)
	}
	var logContent []byte
	if err == nil {
		logContent, _, err = checkpoint.ReadRawSessionLogForCheckpoint(ctx, stores.Persistent, checkpointID)
	}
	if err != nil {
		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
			logging.Debug(ctx, "resume session completed (no metadata)",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("session_id", sessionID),
			)
			fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
			printResumeCmd()
			return nil
		}
		logging.Error(ctx, "resume session failed",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to get session log: %w", err)
	}

	// By default (no --force), decide based on how the local log relates to the
	// checkpoint rather than blindly keeping any existing local log. Mirrors the
	// multi-session policy in strategy.RestoreLogsOnly:
	//   - checkpoint cleanly extends local → overwrite (only appends; nothing lost).
	//   - local newer, or diverged (checkpoint newer but not a clean extension)
	//     → conflict: prompt before overwriting; keep on decline.
	//   - unchanged/no checkpoint timestamp → keep the local log.
	// --force always overwrites.
	if !force {
		if _, statErr := os.Stat(sessionLogPath); statErr == nil {
			localTime := paths.GetLastTimestampFromFile(sessionLogPath)
			checkpointTime := paths.GetLastTimestampFromBytes(logContent)
			status := strategy.ClassifyTimestamps(localTime, checkpointTime)
			// A newer checkpoint timestamp only makes overwriting safe if the
			// checkpoint is a clean forward extension of the local log; otherwise
			// the logs diverged and we must confirm before dropping local entries.
			if status == strategy.StatusCheckpointNewer {
				localBytes, readErr := os.ReadFile(sessionLogPath) //nolint:gosec // sessionLogPath is validated by resolveTranscriptPath
				if readErr != nil || !strategy.TranscriptIsCleanContinuation(localBytes, logContent) {
					status = strategy.StatusDiverged
				}
			}
			switch status {
			case strategy.StatusCheckpointNewer:
				fmt.Fprintf(w, "Checkpoint has newer entries than the local log for '%s'; updating it.\n", sessionID)
				// fall through to the write below
			case strategy.StatusLocalNewer, strategy.StatusDiverged:
				conflict := []strategy.SessionRestoreInfo{{
					SessionID:      sessionID,
					Status:         status,
					LocalTime:      localTime,
					CheckpointTime: checkpointTime,
				}}
				if !strategy.ConfirmOverwriteNewerLocalLogs(errW, conflict) {
					printResumeCmd()
					return nil
				}
				// fall through to the write below
			case strategy.StatusNew, strategy.StatusUnchanged:
				// File present but identical (or no parseable timestamp): keep it.
				fmt.Fprintf(w, "Keeping existing local session log for '%s' (use --force to overwrite from checkpoint).\n", sessionID)
				printResumeCmd()
				return nil
			}
		}
	}

	// Ensure parent directory exists
	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	agentSession := &agent.AgentSession{
		SessionID:  sessionID,
		AgentName:  ag.Name(),
		RepoPath:   repoRoot,
		SessionRef: sessionLogPath,
		NativeData: logContent,
	}

	// Write the session using the agent's WriteSession method
	if err := ag.WriteSession(ctx, agentSession); err != nil {
		logging.Error(ctx, "resume session failed during write",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to write session: %w", err)
	}

	logging.Debug(ctx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", sessionID),
	)

	fmt.Fprintf(w, "✓ Session restored to: %s\n", sessionLogPath)
	fmt.Fprintf(w, "  Session: %s\n", sessionID)
	printResumeCmd()

	return nil
}

func promptFetchFromRemote(branchName string) (bool, error) {
	var confirmed bool

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(fmt.Sprintf("Branch '%s' not found locally. Fetch from origin?", branchName)).
				Value(&confirmed),
		),
	)

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

