				frame = (frame + 1) % len(spinnerFrames)
			}
		}
	}()
	return func(success bool) {
		close(done)
		<-stopped
		if success {
			fmt.Fprintf(w, "\r\033[K✓ %s\n", msg)
			return
		}
		fmt.Fprint(w, "\r\033[K")
	}
