	if !configured {
		return errors.New("no checkpoint_remote configured")
	}
	checkpointURL, err := remote.FetchURL(ctx)
	if err != nil {
		return fmt.Errorf("checkpoint_remote configured but could not resolve URL: %w", err)
	}

